const input = $json.body || $json;

const payload = {
  business_name: String(input.business_name || input.businessName || '').trim(),
  industry: String(input.industry || input.niche || '').trim(),
  product: String(input.product || '').trim(),
  audience: String(input.audience || '').trim(),
  location: String(input.location || input.geo || '').trim(),
  budget: String(input.budget || '').trim(),
  goal: String(input.goal || 'получить лиды').trim(),
};

const required = ['business_name', 'industry', 'product', 'audience', 'location', 'budget', 'goal'];
const missing = required.filter((key) => !payload[key]);
if (missing.length) {
  return [{ json: { ok: false, statusCode: 400, error: 'Missing required fields', missing, received: input } }];
}

const system = `Ты — AI Marketing Analyst.

Твоя задача:
- анализировать бизнес;
- находить точки роста;
- предлагать рекламные гипотезы;
- создавать варианты офферов;
- предлагать идеи рекламных креативов;
- давать следующие шаги.

Работай как практичный performance-маркетолог. Верни только валидный JSON без Markdown.
Формат:
{
  "business_analysis": "",
  "target_audience": [],
  "marketing_hypotheses": [],
  "offer_variants": [],
  "creative_ideas": [],
  "recommended_actions": []
}`;

const prompt = `Проанализируй бизнес и подготовь маркетинговый анализ.

Вводные:
- Название бизнеса: ${payload.business_name}
- Ниша: ${payload.industry}
- Описание продукта: ${payload.product}
- Целевая аудитория: ${payload.audience}
- География: ${payload.location}
- Бюджет на рекламу: ${payload.budget}
- Главная цель: ${payload.goal}

Нужно:
1. Коротко оценить бизнес, продукт, рынок и точки роста.
2. Разложить целевую аудиторию на понятные сегменты.
3. Предложить 3 рекламные гипотезы.
4. Предложить 5 вариантов оффера.
5. Предложить идеи рекламных креативов.
6. Дать список следующих действий на 7 дней.

Пиши на русском языке, конкретно, без воды. Верни строго JSON.`;

const vibe_body = {
  type: 'text',
  model: 'claude-opus-5',
  system,
  prompt,
  max_tokens: 2200,
  effort: 'medium',
  thinking: false,
  idempotency_key: 'marketing-analysis-' + Date.now() + '-' + Math.random().toString(16).slice(2),
};

return [{ json: { ok: true, payload, vibe_body } }];

function stripFences(value) {
  return String(value || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
}

function parseJson(value) {
  const cleaned = stripFences(value);
  try { return JSON.parse(cleaned); } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) return JSON.parse(match[0]);
    throw error;
  }
}

const raw = $json.text || $json.response?.text || '';
const parsed = parseJson(raw);
let estimate = {};
try { estimate = $items('Vibe - Estimate Cost')[0].json; } catch (_) {}

return [{
  json: {
    ok: true,
    business_analysis: parsed.business_analysis || '',
    target_audience: parsed.target_audience || [],
    marketing_hypotheses: parsed.marketing_hypotheses || [],
    offer_variants: parsed.offer_variants || [],
    creative_ideas: parsed.creative_ideas || [],
    recommended_actions: parsed.recommended_actions || [],
    estimate,
    vibe_meta: {
      generation_id: $json.generation_id,
      model: $json.model,
      usage: $json.usage,
      cost: $json.cost,
      reserved: $json.reserved,
      refunded: $json.refunded,
      balance_after: $json.balance_after,
    },
  },
}];

const details = $json.error?.message || $json.message || JSON.stringify($json).slice(0, 1200);
return [{
  json: {
    ok: false,
    statusCode: $json.statusCode || 502,
    error: 'VibeMarketolog API request failed',
    details,
    hint: 'Проверь API ключ в HTTP-ноды: Authorization: Bearer PASTE_VIBE_API_KEY_HERE. У ключа должны быть read/generate scopes и доступный баланс.',
  },
}];
